sys_ui_action.script:
// bfd_ui_issue_provisional_credit — derive the credit amount, enforce the
// 500 approval threshold, then flag the credit on the case.
(function issueProvisionalCreditAction() {
    var TASK_TABLE = 'x_1755386_safetr_0_bfd_case_task';
    var THRESHOLD = 500;
    var engine = new bfd_TriageEngine();

    var amount = parseFloat(current.getValue('provisional_credit_amount') || '0');
    if (isNaN(amount) || amount <= 0) {
        amount = parseFloat(current.getValue('disputed_amount') || '0');
    }
    if (isNaN(amount) || amount <= 0) {
        gs.addErrorMessage(
            'No provisional credit amount could be derived. Enter a Provisional credit amount (or a Disputed amount) and try again.'
        );
        action.setRedirectURL(current);
        return;
    }

    if (current.getValue('provisional_credit_flag') === 'true' || current.getValue('provisional_credit_flag') === '1') {
        gs.addInfoMessage('A provisional credit has already been issued on this case.');
        action.setRedirectURL(current);
        return;
    }

    var canAuthorise =
        gs.hasRole('x_1755386_safetr_0.bfd_team_lead') ||
        gs.hasRole('x_1755386_safetr_0.bfd_admin') ||
        gs.hasRole('admin');

    if (amount > THRESHOLD && !canAuthorise) {
        var approval = new GlideRecord(TASK_TABLE);
        approval.initialize();
        approval.setValue('case', current.getUniqueValue());
        approval.setValue('task_type', 'approval');
        approval.setValue('status', 'open');
        approval.setValue('priority', current.getValue('priority') || 'p2');
        approval.setValue(
            'outcome',
            'Approval requested for a provisional credit of ' +
                amount +
                ' ' +
                (current.getValue('currency') || '') +
                ' (above the ' +
                THRESHOLD +
                ' threshold).'
        );
        if (current.getValue('assigned_group')) approval.setValue('assigned_group', current.getValue('assigned_group'));
        var due = new GlideDateTime();
        due.addDaysLocalTime(1);
        approval.setValue('due_date', due.getValue());
        approval.insert();

        current.setValue('provisional_credit_amount', amount);
        current.setValue('case_status', 'pending_approval');
        engine.logAiDecision(current, {
            note:
                'Agent ' +
                gs.getUserDisplayName() +
                ' requested a provisional credit of ' +
                amount +
                ' which exceeds the ' +
                THRESHOLD +
                ' approval threshold. Case moved to Pending approval; credit NOT applied.',
            finalDecision: 'provisional_credit_pending_approval',
        });
        current.update();

        gs.addInfoMessage(
            'A provisional credit of ' +
                amount +
                ' is above the ' +
                THRESHOLD +
                ' threshold and needs team lead approval. The case is now "Pending approval" and an Approval task has been raised — the credit has NOT been applied yet.'
        );
        action.setRedirectURL(current);
        return;
    }

    current.setValue('provisional_credit_flag', true);
    current.setValue('provisional_credit_amount', amount);
    engine.logAiDecision(current, {
        note:
            'Provisional credit of ' +
            amount +
            ' ' +
            (current.getValue('currency') || '') +
            ' issued by ' +
            gs.getUserDisplayName() +
            '.',
        finalDecision: 'provisional_credit_issued',
    });
    current.update();

    gs.addInfoMessage(
        'Provisional credit of ' + amount + ' issued and recorded on this case, with the decision written to the audit trail.'
    );
    action.setRedirectURL(current);
})();
